"""Problem bank loader. data/problems.json is generated by scripts/build_problems.py.

Public views (list_problems, get_public) never include reference solutions, hidden tests or
hint seeds. The internal accessors (get_reference, get_hidden_tests, get_hint_seeds) are for
grading and the coach only and must never be passed to a response model.
"""

from __future__ import annotations

import json
from functools import lru_cache
from typing import Any

from app.config import ROOT
from app.models import Difficulty, Problem, ProblemDetail, VisibleTest

BANK_PATH = ROOT / "data" / "problems.json"


@lru_cache(maxsize=1)
def _all() -> dict[str, dict[str, Any]]:
    raw = json.loads(BANK_PATH.read_text(encoding="utf-8"))
    return {p["id"]: p for p in raw}


def _raw(problem_id: str) -> dict[str, Any] | None:
    return _all().get(problem_id)


def list_problems() -> list[Problem]:
    return [
        Problem(id=p["id"], title=p["title"], difficulty=p["difficulty"], pattern=p["pattern"])
        for p in _all().values()
    ]


def query(pattern: str | None = None, difficulty: Difficulty | None = None) -> list[Problem]:
    out = []
    for problem in list_problems():
        if pattern is not None and problem.pattern != pattern:
            continue
        if difficulty is not None and problem.difficulty != difficulty:
            continue
        out.append(problem)
    return out


def get_public(problem_id: str) -> ProblemDetail | None:
    p = _raw(problem_id)
    if p is None:
        return None
    return ProblemDetail(
        id=p["id"],
        title=p["title"],
        difficulty=p["difficulty"],
        pattern=p["pattern"],
        statement=p["statement"],
        starter_code=p["starter_code"],
        visible_tests=[VisibleTest(name=t["name"], input=t["input"], expected=t["expected"]) for t in p["visible_tests"]],
    )


# ---------- internal: grading and coaching only ----------


def get_hint_seeds(problem_id: str) -> dict[int, str]:
    p = _raw(problem_id)
    if p is None:
        raise KeyError(problem_id)
    return {int(level): text for level, text in p["hint_seeds"].items()}


def get_reference(problem_id: str) -> str:
    p = _raw(problem_id)
    if p is None:
        raise KeyError(problem_id)
    return p["reference_solution"]


def get_hidden_tests(problem_id: str) -> list[dict[str, Any]]:
    p = _raw(problem_id)
    if p is None:
        raise KeyError(problem_id)
    return list(p["hidden_tests"])


def get_expected_complexity(problem_id: str) -> str:
    p = _raw(problem_id)
    if p is None:
        raise KeyError(problem_id)
    return p["expected_complexity"]
